"""Export pipeline constants to app/src/generated/constants.json.

The browser flux computation (src/cell/flux.ts) must use exactly the constants
in pipeline/src/dune_atlas_pipeline/constants.py. Re-run after changing them:

    PYTHONPATH=pipeline/src python app/scripts/export-constants.py
"""
import json
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "pipeline" / "src"))
from dune_atlas_pipeline import constants as C  # noqa: E402

out = {
    "_comment": "GENERATED by app/scripts/export-constants.py from pipeline constants.py - do not edit",
    "Z": C.Z, "Z0": C.Z0, "KAPPA": C.KAPPA, "BETA": C.BETA, "DASPECT": C.DASPECT, "G": C.G,
    "RHO_S": C.RHO_S, "RHO_F": C.RHO_F, "FLUXCONSTANT": C.FLUXCONSTANT, "FLUXK": C.FLUXK,
    "S2Y": C.S2Y, "N_HOURS": C.N_HOURS, "UT_DEFAULT_INDEX": C.UT_DEFAULT_INDEX,
    # repr-exact float64 lists (json writes shortest round-trip repr)
    "UM_EDGES": C.UM_EDGES.tolist(), "UA_EDGES": C.UA_EDGES.tolist(),
    "UM_CENTRES": C.UM_CENTRES.tolist(), "UA_CENTRES": C.UA_CENTRES.tolist(),
    "UT_VALUES": C.UT_VALUES.tolist(),
    # fields withheld from the atlas (none)
    "QSAT_VARS": list(C.QSAT_VARS), "WITHHELD_VARS": list(C.WITHHELD_VARS),
}
dst = ROOT / "app" / "src" / "generated" / "constants.json"
dst.write_text(json.dumps(out, indent=1) + "\n")
print(dst, len(out))
